from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Initialize an empty list to store separate groups
    separate_groups = []

    # Step 3: Iterate through the input string
    i = 0
    while i < len(paren_string):
        # Step 4: Identify and extract each separate parentheses group
        if paren_string[i] == '(':
            count = 1
            j = i + 1
            while j < len(paren_string):
                if paren_string[j] == '(':
                    count += 1
                elif paren_string[j] == ')':
                    count -= 1
                if count == 0:
                    separate_groups.append(paren_string[i:j+1])
                    break
                j += 1
            i = j + 1
        else:
            i += 1

    # Step 5: Check if the group is balanced
    def is_balanced(group):
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return not stack

    # Step 6: Add the balanced group to the list
    separate_groups = [group for group in separate_groups if is_balanced(group)]

    # Step 7: Return the list of separate groups
    return separate_groups

# Test the function with the provided example
print(separate_paren_groups('( ) (( )) (( )( ))'))  # Output: ['()', '(())', '(()())']

